// What: fills missing process environment values from the repository .env file.
// Why: the SmartSpectra key lives in .env, and neither Electron nor Node reads that file on its own.
// Removed: a copied .env would be ignored and the camera would never receive its key.
import { readFileSync } from 'node:fs';

export type EnvLoadResult =
  | { found: true; path: string; loadedKeys: string[] }
  | { found: false; path: string };

const KEY = /^[A-Z_][A-Z0-9_]*$/;

export function loadEnvFile(filePath: string, env: NodeJS.ProcessEnv): EnvLoadResult {
  let text: string;
  try {
    text = readFileSync(filePath, 'utf8');
  } catch {
    return { found: false, path: filePath };
  }
  const loadedKeys: string[] = [];
  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (line === '' || line.startsWith('#')) continue;
    const body = line.startsWith('export ') ? line.slice('export '.length).trim() : line;
    const equals = body.indexOf('=');
    if (equals <= 0) continue;
    const key = body.slice(0, equals).trim();
    if (!KEY.test(key)) continue;
    // A value already exported by the shell wins over the file.
    if (env[key] !== undefined && env[key] !== '') continue;
    env[key] = unquote(body.slice(equals + 1).trim());
    loadedKeys.push(key);
  }
  return { found: true, path: filePath, loadedKeys };
}

export function readSensingKey(env: NodeJS.ProcessEnv): string {
  const value = env.SMARTSPECTRA_API_KEY;
  return typeof value === 'string' && value.trim().length > 0 ? value.trim() : '';
}

function unquote(value: string): string {
  const first = value[0];
  const last = value[value.length - 1];
  if (value.length >= 2 && (first === '"' || first === "'") && last === first) {
    return value.slice(1, -1);
  }
  return value;
}

// What: turns one SmartSpectra payload into the numbers this app stores, and names SDK failures.
// Why: the SDK speaks epoch microseconds and protobuf; the session speaks one clock and five fields.
// Removed: a pulse could land at the wrong instant, and a failure would surface as a bare code.
import { z } from 'zod';
import {
  validationMessageSchema,
  type PulseSample,
  type SessionAnchor,
  type ValidationMessage,
} from '../shared/contracts.js';

/**
 * The SDK's integer codes, copied here so this module loads without the native binding.
 * Values are stable across SDK versions (docs/nodejs/api-reference).
 */
export const SDK_ERROR = {
  invalidState: 1,
  authenticationFailed: 2,
  configurationFailed: 3,
  creditExhausted: 4,
  networkError: 5,
  serverError: 6,
  inputUnavailable: 7,
  processingFailed: 8,
  frameConversionFailed: 9,
  nonMonotonicTimestamp: 10,
  timestampGap: 11,
  metricNotAuthorized: 13,
  sustainedLowFrameRate: 14,
} as const;

export const VALIDATION = {
  ok: 0,
  noFaceFound: 1,
  multipleFacesFound: 2,
  faceNotCentered: 3,
  faceSizeOutOfRange: 4,
  tooDark: 5,
  tooBright: 6,
  chestNotVisible: 7,
  cameraTuning: 10,
  frameRateTooLow: 11,
  excessiveMotion: 12,
  faceTooClose: 13,
  faceTooFar: 14,
  faceTooHigh: 15,
  faceTooLow: 16,
  faceNotForward: 17,
} as const;

/** A pulse outside this range is a decoding mistake, not a reading. Kept narrow on purpose. */
const MIN_PULSE_BPM = 20;
const MAX_PULSE_BPM = 300;
const MAX_TEXT_LENGTH = 240;

const readingSchema = z.object({
  value: z.number().finite(),
  confidence: z.number().finite().min(0).max(100),
  stable: z.boolean(),
  timestamp: z.unknown(),
});

const VALIDATION_COPY: Record<number, string> = {
  [VALIDATION.ok]: 'Measuring.',
  [VALIDATION.noFaceFound]: 'Waiting for a face.',
  [VALIDATION.multipleFacesFound]: 'More than one face is in view.',
  [VALIDATION.faceNotCentered]: 'Center your face in the frame.',
  [VALIDATION.faceSizeOutOfRange]: 'Move so your face fills the frame.',
  [VALIDATION.tooDark]: 'Too dark. Add light in front of you.',
  [VALIDATION.tooBright]: 'Too bright. Reduce the light behind you.',
  [VALIDATION.chestNotVisible]: 'Sit back so your chest is in frame.',
  [VALIDATION.cameraTuning]: 'The camera is still adjusting.',
  [VALIDATION.frameRateTooLow]: 'The camera frame rate is too low.',
  [VALIDATION.excessiveMotion]: 'Too much movement. Hold still.',
  [VALIDATION.faceTooClose]: 'Move a little further from the camera.',
  [VALIDATION.faceTooFar]: 'Move a little closer to the camera.',
  [VALIDATION.faceTooHigh]: 'Lower your face into the frame.',
  [VALIDATION.faceTooLow]: 'Raise your face into the frame.',
  [VALIDATION.faceNotForward]: 'Face the camera.',
};

const SDK_ERROR_COPY: Record<number, string> = {
  [SDK_ERROR.invalidState]: 'The sensing pipeline was not ready. Start the session again.',
  [SDK_ERROR.authenticationFailed]: 'The SmartSpectra key was rejected. Check SMARTSPECTRA_API_KEY in .env.',
  [SDK_ERROR.configurationFailed]: 'The sensing configuration was rejected.',
  [SDK_ERROR.creditExhausted]: 'This SmartSpectra key has no measurement credit left.',
  [SDK_ERROR.networkError]: 'The network check for the sensing key failed. Try again when you are online.',
  [SDK_ERROR.serverError]: 'The sensing service is unavailable right now.',
  [SDK_ERROR.inputUnavailable]: 'No camera was available.',
  [SDK_ERROR.processingFailed]: 'The camera pipeline failed.',
  [SDK_ERROR.frameConversionFailed]: 'The camera frames could not be read.',
  [SDK_ERROR.nonMonotonicTimestamp]: 'The camera clock moved backwards.',
  [SDK_ERROR.timestampGap]: 'The camera stopped sending frames.',
  [SDK_ERROR.metricNotAuthorized]: 'This SmartSpectra key is not allowed to measure pulse.',
  [SDK_ERROR.sustainedLowFrameRate]: 'The camera frame rate stayed too low.',
};

/**
 * The newest pulse reading in a decoded metrics payload, already on the session clock.
 * Weak samples are kept: the raw trace keeps them and coverage is what falls.
 */
export function latestPulseSample(
  payload: unknown,
  anchor: SessionAnchor,
  lastTUs: number,
): PulseSample | null {
  const series = pulseSeries(payload);
  if (!series) return null;
  return toPulseSample(series[series.length - 1], anchor, lastTUs);
}

export function toPulseSample(
  raw: unknown,
  anchor: SessionAnchor,
  lastTUs: number,
): PulseSample | null {
  const parsed = readingSchema.safeParse(raw);
  if (!parsed.success) return null;
  if (parsed.data.value < MIN_PULSE_BPM || parsed.data.value > MAX_PULSE_BPM) return null;
  const timestamp = epochUs(parsed.data.timestamp);
  if (timestamp === null) return null;
  const tUs = anchor.monoUs + (timestamp - anchor.epochMs * 1000);
  if (!Number.isSafeInteger(tUs) || tUs < anchor.monoUs || tUs <= lastTUs) return null;
  return {
    tUs,
    bpm: parsed.data.value,
    confidence: parsed.data.confidence,
    stable: parsed.data.stable,
  };
}

export function validationMessage(
  code: number,
  timestampUs: number,
  hint: string,
  anchor: SessionAnchor,
): ValidationMessage | null {
  const timestamp = epochUs(timestampUs);
  if (timestamp === null) return null;
  const tUs = anchor.monoUs + (timestamp - anchor.epochMs * 1000);
  if (!Number.isSafeInteger(tUs) || tUs < 0) return null;
  return validationMessageSchema.parse({ code, ts: tUs, hint: validationText(code, hint) });
}

export function validationText(code: number, hint: string): string {
  const trimmed = typeof hint === 'string' ? hint.trim() : '';
  if (trimmed.length > 0) return truncate(trimmed);
  return VALIDATION_COPY[code] ?? 'Measuring.';
}

export function sdkErrorMessage(code: number, detail: string): string {
  const copy = SDK_ERROR_COPY[code];
  if (copy) return copy;
  const trimmed = typeof detail === 'string' ? truncate(detail.trim()) : '';
  return trimmed.length > 0
    ? `${trimmed} (sensing code ${code})`
    : `Sensing stopped unexpectedly (code ${code}).`;
}

function pulseSeries(payload: unknown): unknown[] | null {
  if (typeof payload !== 'object' || payload === null) return null;
  const cardio = (payload as { cardio?: unknown }).cardio;
  if (typeof cardio !== 'object' || cardio === null) return null;
  const series = (cardio as { pulseRate?: unknown }).pulseRate;
  if (!Array.isArray(series) || series.length === 0) return null;
  return series;
}

/** protobufjs hands int64 back as a Long, so accept a number or anything with toNumber(). */
function epochUs(value: unknown): number | null {
  if (typeof value === 'number') return isEpochUs(value) ? value : null;
  if (typeof value === 'object' && value !== null) {
    const toNumber = (value as { toNumber?: unknown }).toNumber;
    if (typeof toNumber === 'function') {
      const converted = (toNumber as () => unknown).call(value);
      if (typeof converted === 'number' && isEpochUs(converted)) return converted;
    }
  }
  return null;
}

function isEpochUs(value: number): boolean {
  return Number.isSafeInteger(value) && value > 0;
}

function truncate(text: string): string {
  return text.length > MAX_TEXT_LENGTH ? `${text.slice(0, MAX_TEXT_LENGTH - 1)}…` : text;
}

// What: owns the one SmartSpectra measurement session in the main process.
// Why: the key and the native camera runtime must stay outside the page, which receives only numbers.
// Removed: nothing would open the camera, so a real session would store no pulse.
import {
  CameraSelection,
  ProcessingStatus,
  SmartSpectraErrorCode,
  SmartSpectraLogLevel,
  SmartSpectraSDK,
  cardioMetrics,
} from '@smartspectra/node-sdk';
import { decodeMetrics } from '@smartspectra/node-sdk/messages';
import type { PulseSample, SdkError, SessionAnchor, ValidationMessage } from '../shared/contracts.js';
import { latestPulseSample, sdkErrorMessage, validationMessage } from './capture-samples.js';

/** Coalesce readings so the page and the store see roughly four batches a second. */
const FLUSH_MS = 250;
/** A blocked native stop must not hold the window hostage. */
const STOP_TIMEOUT_MS = 8_000;

export interface CaptureEvents {
  onSamples(samples: PulseSample[]): void | Promise<void>;
  onValidation(message: ValidationMessage): void;
  onError(error: SdkError): void;
}

export interface CaptureSession {
  stop(): Promise<void>;
}

export function startCapture(input: {
  apiKey: string;
  anchor: SessionAnchor;
  events: CaptureEvents;
}): CaptureSession {
  const sdk = new SmartSpectraSDK({
    apiKey: input.apiKey,
    requestedMetrics: [...cardioMetrics],
    // Session summaries would leave the machine; ChessPulse is local-only.
    enableTelemetry: false,
    logLevel: SmartSpectraLogLevel.kWarning,
  });
  let pending: PulseSample[] = [];
  let lastTUs = input.anchor.monoUs;
  let timer: NodeJS.Timeout | undefined;
  let closed = false;
  let stopping: Promise<void> | undefined;
  let reported = false;

  function flush(): void {
    if (timer !== undefined) {
      clearTimeout(timer);
      timer = undefined;
    }
    if (pending.length === 0) return;
    const batch = pending;
    pending = [];
    try {
      const run = input.events.onSamples(batch);
      if (run && typeof run.then === 'function') {
        // A refused batch means the session is gone; release the camera with it.
        void run.then(undefined, () => {
          void shutdown();
        });
      }
    } catch {
      void Promise.resolve().then(() => shutdown());
    }
  }

  function emitError(error: SdkError): void {
    if (closed) return;
    reported = true;
    input.events.onError(error);
  }

  function shutdown(): Promise<void> {
    if (stopping) return stopping;
    closed = true;
    stopping = Promise.resolve().then(async () => {
      flush();
      try {
        await beforeDeadline(sdk.stopAsync(), STOP_TIMEOUT_MS);
      } catch {
        // The pipeline is already gone. destroy() below still releases the camera handle.
      }
      try {
        await sdk.destroy();
      } catch {
        // Nothing is left to release.
      }
    });
    return stopping;
  }

  sdk.on('metrics', (buffer) => {
    if (closed) return;
    let payload: unknown;
    try {
      payload = decodeMetrics(buffer);
    } catch {
      return;
    }
    const sample = latestPulseSample(payload, input.anchor, lastTUs);
    if (!sample) return;
    lastTUs = sample.tUs;
    pending.push(sample);
    if (timer === undefined) timer = setTimeout(flush, FLUSH_MS);
  });

  sdk.on('validationStatus', (code, timestampUs, hint) => {
    if (closed) return;
    const message = validationMessage(code, timestampUs, hint, input.anchor);
    if (message) input.events.onValidation(message);
  });

  sdk.on('error', (code, message, retryable) => {
    emitError({ code, message: sdkErrorMessage(code, message), retryable });
    if (!retryable) void shutdown();
  });

  sdk.on('processingStatus', (status) => {
    if (status !== ProcessingStatus.kError || reported) return;
    emitError({
      code: SmartSpectraErrorCode.kProcessingFailed,
      message: sdkErrorMessage(SmartSpectraErrorCode.kProcessingFailed, ''),
      retryable: false,
    });
    void shutdown();
  });

  sdk.useCamera(CameraSelection.default);
  try {
    sdk.start();
  } catch (error) {
    closed = true;
    void sdk.destroy().catch(() => undefined);
    throw new Error(sdkErrorMessage(errorCode(error), errorText(error)));
  }

  return { stop: shutdown };
}

function errorCode(error: unknown): number {
  if (typeof error === 'object' && error !== null && 'code' in error) {
    const code = (error as { code?: unknown }).code;
    if (typeof code === 'number') return code;
  }
  return SmartSpectraErrorCode.kProcessingFailed;
}

function errorText(error: unknown): string {
  return error instanceof Error ? error.message : '';
}

function beforeDeadline(work: Promise<void>, ms: number): Promise<void> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('The sensing pipeline did not stop in time.')), ms);
    timer.unref();
    work.then(
      () => {
        clearTimeout(timer);
        resolve();
      },
      (error: unknown) => {
        clearTimeout(timer);
        reject(error);
      },
    );
  });
}

