// What: the camera preview, and the only place frames are captured.
// Why: the player must see their own framing, and the SDK needs those same frames in the main process.
// Removed: the page would show nothing to aim at, and sensing quality would stay a guess.
import { useCallback, useEffect, useRef, useState } from 'react';
import { lightNote, previewBoost } from '../shared/preview';

/** Fallback pacing when the browser has no per-frame callback. */
const FRAME_INTERVAL_MS = 33;
/** The SDK measures pulse, not detail; 480 px wide keeps the IPC payload small. */
const MAX_FRAME_WIDTH = 480;
/** Chromium stops presenting frames while the window is minimised; this is how long to wait before reconnecting. */
const STALL_MS = 2_500;
const MAX_RESTARTS = 5;

export type PreviewState = 'starting' | 'ready' | 'error';

export function CameraPreview({
  sensing,
  onError,
}: {
  sensing: boolean;
  onError: (message: string | null) => void;
}) {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const onErrorRef = useRef(onError);
  onErrorRef.current = onError;
  const lastFrameAt = useRef(0);
  const restarts = useRef(0);
  const [state, setState] = useState<PreviewState>('starting');
  const [error, setError] = useState<string | null>(null);
  const [light, setLight] = useState<number | null>(null);
  const [reconnecting, setReconnecting] = useState(false);
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    let cancelled = false;
    const video = videoRef.current;
    setState('starting');
    navigator.mediaDevices
      .getUserMedia({
        video: {
          width: { ideal: 1280 },
          height: { ideal: 720 },
          frameRate: { ideal: 30 },
        },
        audio: false,
      })
      .then((stream) => {
        if (cancelled) {
          stopStream(stream);
          return;
        }
        streamRef.current = stream;
        if (video) {
          video.srcObject = stream;
          void video.play().catch(() => undefined);
        }
        setState('ready');
        setError(null);
        setReconnecting(false);
        onErrorRef.current(null);
      })
      .catch((caught: unknown) => {
        if (cancelled) return;
        const message = cameraMessage(caught);
        setState('error');
        setError(message);
        setReconnecting(false);
        onErrorRef.current(message);
      });
    return () => {
      cancelled = true;
    };
  }, [attempt]);

  useEffect(
    () => () => {
      stopStream(streamRef.current);
      streamRef.current = null;
      onErrorRef.current(null);
    },
    [],
  );

  useEffect(() => {
    if (state !== 'ready') return undefined;
    const video = videoRef.current;
    if (!video) return undefined;
    const canvas = document.createElement('canvas');
    canvas.width = 48;
    canvas.height = 36;
    const context = canvas.getContext('2d', { willReadFrequently: true });
    if (!context) return undefined;
    let stopped = false;
    let timer: number | undefined;
    const sample = (): void => {
      if (stopped) return;
      if (video.videoWidth > 0 && video.videoHeight > 0) {
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const data = context.getImageData(0, 0, canvas.width, canvas.height).data;
        let sum = 0;
        for (let index = 0; index < data.length; index += 4) {
          sum += 0.2126 * data[index] + 0.7152 * data[index + 1] + 0.0722 * data[index + 2];
        }
        setLight(sum / (canvas.width * canvas.height) / 255);
      }
      timer = window.setTimeout(sample, 500);
    };
    sample();
    return () => {
      stopped = true;
      if (timer !== undefined) window.clearTimeout(timer);
    };
  }, [state]);

  useEffect(() => {
    if (!sensing || state !== 'ready') return undefined;
    const video = videoRef.current;
    const send = window.chesspulse?.sendFrame;
    if (!video || !send) return undefined;
    const canvas = document.createElement('canvas');
    const context = canvas.getContext('2d', { willReadFrequently: true });
    if (!context) return undefined;

    let stopped = false;
    let timer: number | undefined;
    let frameHandle: number | undefined;
    let lastTs = 0;

    const push = (): void => {
      const sourceWidth = video.videoWidth;
      const sourceHeight = video.videoHeight;
      if (sourceWidth === 0 || sourceHeight === 0) return;
      const scale = Math.min(1, MAX_FRAME_WIDTH / sourceWidth);
      const width = Math.max(2, Math.round(sourceWidth * scale));
      const height = Math.max(2, Math.round(sourceHeight * scale));
      if (canvas.width !== width) canvas.width = width;
      if (canvas.height !== height) canvas.height = height;
      context.drawImage(video, 0, 0, width, height);
      const image = context.getImageData(0, 0, width, height);
      const nowUs = Math.round((performance.timeOrigin + performance.now()) * 1000);
      const timestampUs = Math.max(lastTs + 1, nowUs);
      lastTs = timestampUs;
      lastFrameAt.current = Date.now();
      try {
        send(image.data.buffer as ArrayBuffer, width, height, timestampUs);
      } catch {
        // A refused frame is dropped; the next one is a fresh copy.
      }
    };

    // One frame per real camera frame: no duplicates and no missed ones. The clock drives the
    // timestamps, and the SDK measures frame rate from them.
    if ('requestVideoFrameCallback' in video) {
      const onFrame = (): void => {
        if (stopped) return;
        push();
        frameHandle = video.requestVideoFrameCallback(onFrame);
      };
      frameHandle = video.requestVideoFrameCallback(onFrame);
    } else {
      const step = (): void => {
        if (stopped) return;
        push();
        timer = window.setTimeout(step, FRAME_INTERVAL_MS);
      };
      step();
    }

    return () => {
      stopped = true;
      if (timer !== undefined) window.clearTimeout(timer);
      if (frameHandle !== undefined) video.cancelVideoFrameCallback(frameHandle);
    };
  }, [sensing, state]);

  const reconnect = useCallback(() => {
    if (restarts.current >= MAX_RESTARTS) {
      const message = 'The camera stopped sending frames. Press Revoke camera consent, then Allow the camera.';
      setState('error');
      setError(message);
      onErrorRef.current(message);
      return;
    }
    restarts.current += 1;
    setReconnecting(true);
    stopStream(streamRef.current);
    streamRef.current = null;
    lastFrameAt.current = Date.now();
    setAttempt((value) => value + 1);
  }, []);

  useEffect(() => {
    if (!sensing || state !== 'ready') return undefined;
    lastFrameAt.current = Date.now();
    const watchdog = window.setInterval(() => {
      if (Date.now() - lastFrameAt.current > STALL_MS) reconnect();
    }, 1_000);
    return () => window.clearInterval(watchdog);
  }, [sensing, state, reconnect]);

  const boost = previewBoost(light);

  return (
    <figure className="camera">
      <video
        ref={videoRef}
        className="camera-video"
        style={boost > 1 ? { filter: `brightness(${boost.toFixed(2)}) contrast(1.15)` } : undefined}
        muted
        playsInline
        autoPlay
        aria-hidden="true"
      />
      <figcaption className="hint">
        {state === 'error'
          ? error
          : state === 'starting'
            ? 'Opening the camera…'
            : reconnecting
              ? 'Reconnecting the camera…'
              : lightNote(light)}
      </figcaption>
    </figure>
  );
}

function stopStream(stream: MediaStream | null): void {
  if (!stream) return;
  for (const track of stream.getTracks()) track.stop();
}

function cameraMessage(caught: unknown): string {
  const name = typeof caught === 'object' && caught !== null && 'name' in caught
    ? String((caught as { name?: unknown }).name)
    : '';
  if (name === 'NotAllowedError' || name === 'SecurityError') {
    return 'The camera was blocked. Allow the camera, then try again.';
  }
  if (name === 'NotFoundError' || name === 'OverconstrainedError') {
    return 'No camera was found.';
  }
  if (name === 'NotReadableError' || name === 'AbortError') {
    return 'The camera is already in use by another app.';
  }
  return 'The camera could not be opened.';
}

